(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:d}):'—',clamp=(v,a,b)=>Math.max(a,Math.min(b,v));const button=(key,label,value='',row=null)=>'<button type="button" class="visual-chip" data-visual-field="'+esc(key)+'"'+(row!==null?' data-visual-row="'+row+'"':'')+'><span>'+esc(label)+'</span>'+(value?'<strong>'+esc(value)+'</strong>':'')+'</button>';const svg=body=>'<svg class="engineering-drawing" viewBox="0 0 420 220" aria-hidden="true">'+body+'</svg>';const label=(x,y,t)=>'<text x="'+x+'" y="'+y+'" text-anchor="middle" fill="#42655d" font-size="12">'+esc(t)+'</text>';const arrow='<path d="M80 160h260m-12-8 12 8-12 8" fill="none" stroke="#179782" stroke-width="3"/>';function section(title,body,keys,note=''){return '<details class="engineering-visual"'+((document.querySelector('.engineering-visual')?.open??(!window.matchMedia('(max-width:700px)').matches&&!['duct','water'].includes(document.body.dataset.handoff)))?' open':'')+'><summary>'+esc(title)+'<span>'+L('Ẩn / hiện','Hide / show')+'</span></summary><div class="engineering-visual-body">'+body+'<div class="visual-actions">'+keys+'</div><p class="visual-caption">'+esc(note||L('Hình minh họa, không theo tỷ lệ. Nhấn thông số để đến ô nhập chi tiết.','Illustration, not to scale. Select a parameter to reach its detailed input.'))+'</p></div></details>';}
function geometry(round,a,b,flow,v){const ratio=round?1:a/b,w=round?122:clamp(130*Math.sqrt(ratio),80,250),h=round?122:clamp(w/ratio,25,140),x=210-w/2,y=95-h/2;return svg((round?'<circle cx="210" cy="95" r="61" fill="#dbefeb" stroke="#5c9b8b" stroke-width="4"/>':'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="4" fill="#dbefeb" stroke="#5c9b8b" stroke-width="4"/>')+label(210,round?28:Math.max(18,y-12),round?'Ø '+n(a,0)+' mm':n(a,0)+' × '+n(b,0)+' mm')+arrow+label(210,205,'Q = '+n(flow)+' m³/h · v = '+n(v)+' m/s'));}
function render(key,x,r){let body='',buttons='';if(key==='grille'){const round=x.kind==='round',square=x.kind==='fourway',h=square?x.width:x.height,w=square?120:250,bh=square?120:clamp(w*h/x.width,14,120);const shape=round?'<circle cx="210" cy="86" r="57" fill="#dcf0ea" stroke="#61958b" stroke-width="4"/><circle cx="210" cy="86" r="37" fill="none" stroke="#87b4a9" stroke-width="4"/>':'<rect x="'+(210-w/2)+'" y="'+(90-bh/2)+'" width="'+w+'" height="'+bh+'" rx="4" fill="#dcefe8" stroke="#5d9c8c" stroke-width="3"/>'+[1,2,3].map(i=>'<path d="M'+(220-w/2)+' '+(90-bh/2+i*bh/4)+'h'+(w-20)+'" stroke="#87b4a9" stroke-width="2"/>').join('');body=svg(shape+label(210,20,round?'Ø '+n(x.width,0)+' mm':n(x.width,0)+' × '+n(h,0)+' mm')+(square?'<path d="M210 52v-21m-6 7 6-7 6 7M210 145v26m-6-7 6 7 6-7M145 90h-35m7-6-7 6 7 6M275 90h35m-7-6 7 6-7 6" fill="none" stroke="#159e8c" stroke-width="3"/>':'<path d="M210 150v28m-7-8 7 8 7-8M165 146l-30 26m2-10-2 10 10-1M255 146l30 26m-2-10 2 10-10-1" fill="none" stroke="#159e8c" stroke-width="3"/>')+label(210,205,L('Mỗi miệng: ','Per grille: ')+n(r.each)+' m³/h'));buttons=button('kind',L('Loại miệng','Type'))+button('width',L('Kích thước mặt','Face size'))+button('count',L('Số miệng','Count'),n(x.count,0))+button('free',L('Diện tích hữu dụng','Free area'),n(x.free)+'%');return section(L('Miệng gió đang kiểm tra','Checked diffuser / grille'),body,buttons,L('Mũi tên chỉ minh họa hướng cấp khí; không thể hiện tầm thổi, độ rơi hoặc độ ồn.','Arrows illustrate supply airflow, not throw, drop or noise.'));}
if(key==='fan'||key==='pump'){const fan=key==='fan',total=r.detail.reduce((s,d)=>s+d.total,0);body='<div class="visual-path">'+r.detail.map((d,i)=>'<button type="button" class="visual-node" data-visual-field="length" data-visual-row="'+i+'"><span class="visual-node-number">'+(i+1)+'</span><strong>'+esc(d.name)+'</strong><small>'+esc(n(d.flow)+' m³/h · '+(fan?(d.shape==='round'?'Ø '+n(d.a):n(d.a)+' × '+n(d.b)):'Ø '+n(d.d))+' mm')+'</small><b>'+n(d.total)+' '+(fan?'Pa':'mH₂O')+'</b><span class="visual-loss-bar"><i style="width:'+clamp(total>0?d.total/total*100:0,0,100)+'%"></i></span></button>').join('<span class="visual-path-arrow" aria-hidden="true">→</span>')+'</div>';if(!fan)body+='<p class="visual-system">'+esc(x.system==='closed'?L('Vòng kín: không cộng chiều cao tòa nhà vào cột áp.','Closed loop: building height is not added to pump head.'):L('Hệ hở: cộng chênh cao và áp suất dư tại điểm dùng.','Open system: elevation and terminal residual pressure are added.'))+'</p>';buttons=button('flow',L('Lưu lượng thiết bị','Duty flow'),n(x.flow)+' m³/h')+button('margin',L('Dự phòng','Allowance'),n(x.margin)+'%');return section(L('Tuyến bất lợi & phân bổ tổn thất','Critical path & loss distribution'),body,buttons,L('Các nút là các đoạn nối tiếp trên tuyến đã nhập, không phải các nhánh song song. Thanh màu biểu thị tỷ trọng tổn thất của đoạn trong tổng tổn thất tuyến.','Nodes are entered sections in series, not parallel branches. Bars show each section’s share of summed path loss.'));}
if(key==='insulation'){const inner=35,outer=clamp(inner*(1+2*x.thickness/x.d),35,85);body=svg((r.rect?'<rect x="47" y="55" width="170" height="106" fill="#d9b889" stroke="#ad986f"/><rect x="62" y="70" width="140" height="76" fill="#9edbdf" stroke="#5c929b" stroke-width="4"/>':'<circle cx="132" cy="108" r="'+outer+'" fill="#d9b889" stroke="#ad986f" stroke-width="2"/><circle cx="132" cy="108" r="35" fill="#9edbdf" stroke="#5c929b" stroke-width="5"/>')+label(132,18,(r.rect?n(x.width)+' × '+n(x.height):'Ø '+n(x.d))+' mm · '+n(x.thickness)+' mm')+label(132,112,n(x.pipe)+' °C')+'<path d="M'+(132+outer)+' 108h35" stroke="#bd9e70" stroke-width="2"/>'+label(305,83,L('Bề mặt','Surface'))+label(305,106,n(r.selected.surface)+' °C')+label(305,144,L('Điểm sương','Dew point')+': '+n(r.dp)+' °C'));body+='<div class="visual-state '+(r.selected.pass?'pass':'warn')+'">'+L('Với dự phòng đã nhập: ','With entered allowance: ')+(r.selected.pass?L('Đạt mục tiêu đã nhập','Entered targets met'):L('Chưa đạt mục tiêu đã nhập','Entered targets not met'))+'</div>';buttons=button('thickness',L('Chiều dày','Thickness'),n(x.thickness)+' mm')+button('rh',L('Độ ẩm','Humidity'),n(x.rh)+'%')+button('ambient',L('Nhiệt độ môi trường','Ambient'),n(x.ambient)+' °C');return section(L('Mặt cắt cách nhiệt','Insulation cross-section'),body,buttons);}
if(key==='expansion'){const V=r.chosen||r.nominal,cold=V*r.initialFraction,hot=cold+r.expanded;function tank(value,title,temp){return '<div class="visual-tank-state"><strong>'+esc(title)+'</strong><div class="visual-tank"><div class="visual-water" style="height:'+clamp(value/V*100,0,100)+'%"></div><span>'+n(value)+' L</span></div><small>'+n(temp)+' °C</small></div>';}body='<div class="visual-tanks">'+tank(cold,L('Nước lạnh','Cold water'),x.cold)+'<span aria-hidden="true">→</span>'+tank(hot,L('Nước nóng','Hot water'),x.hot)+'</div><p class="visual-system">'+L('Dung tích bình minh họa: ','Illustrated vessel volume: ')+n(V)+' L · '+L('Nước giãn nở thêm: ','Additional expansion: ')+n(r.expanded)+' L</p>';buttons=button('volume',L('Thể tích hệ','System volume'),n(x.volume)+' L')+button('pre',L('Nạp khí','Pre-charge'),n(x.pre)+' bar')+button('fill',L('Nạp nước lạnh','Cold fill'),n(x.fill)+' bar');return section(L('Phần khí / nước trong bình','Gas / water in the vessel'),body,buttons,L('Vùng xanh là lượng nước ban đầu cộng phần giãn nở khi nóng; phần còn lại là khí. Hình tính theo dung tích bình đề xuất, hoặc dung tích yêu cầu nếu ngoài dải gợi ý.','Blue shows initial water plus thermal expansion; the remainder is gas. Uses the proposed vessel volume, or required volume when outside the suggested range.'));}
if(key==='flow'){body='<div class="visual-flow"><div class="visual-flow-source">'+n(r.kw)+'<small>kW</small></div><span aria-hidden="true">→</span><div><div class="visual-flow-result">'+L('Gió cấp','Supply air')+'<strong>'+n(r.air)+' m³/h</strong><small>'+L('Theo tải nhiệt hiện','From sensible load')+'</small></div><div class="visual-flow-result">'+L('Nước lạnh','Chilled water')+'<strong>'+n(r.water)+' m³/h</strong><small>'+L('Theo tải tổng','From total load')+'</small></div></div></div>';buttons=button('load',L('Tải lạnh','Cooling load'))+button('airDt','ΔT '+L('gió','air'),n(x.airDt)+' °C')+button('waterDt','ΔT '+L('nước','water'),n(x.waterDt)+' °C');return section(L('Tải lạnh → lưu lượng','Cooling load → flow'),body,buttons);}
if(key==='ventilation'){body=svg('<path d="M70 90l140-65 140 65v94H70z" fill="#e0f0e8" stroke="#76a798" stroke-width="3"/><path d="M25 120h73m-12-7 12 7-12 7M324 120h73m-12-7 12 7-12 7" fill="none" stroke="#19a492" stroke-width="4"/>'+Array.from({length:Math.min(x.people,8)},(_,i)=>{const cx=113+i%4*55,cy=121+Math.floor(i/4)*35;return '<circle cx="'+cx+'" cy="'+cy+'" r="6" fill="#518b89"/><path d="M'+cx+' '+(cy+8)+'v12" stroke="#518b89" stroke-width="7" stroke-linecap="round"/>';}).join('')+label(210,85,n(x.people,0)+' '+L('người','people')+' · '+n(x.area)+' m²')+label(210,211,n(r.chosen)+' m³/h · '+n(r.ach)+' '+L('lần/giờ','ACH')));buttons=button('people',L('Số người','Occupants'),n(x.people,0))+button('area',L('Diện tích','Area'),n(x.area)+' m²')+button('method',L('Phương pháp','Method'));return section(L('Thông gió căn phòng','Room ventilation'),body,buttons,L('Hình người chỉ minh họa, tối đa 8 biểu tượng. Số người và lưu lượng tính dùng đúng thông số nhập; hướng mũi tên không xác định vị trí cấp/hút thiết kế.','At most 8 person symbols are shown. Calculations use the entered occupant count; arrows do not define designed inlet/exhaust locations.'));}
return '';}
function focus(event){const b=event.target.closest('[data-visual-field]');if(!b)return;const el=b.dataset.visualRow!==undefined?document.querySelector('[data-row="'+b.dataset.visualRow+'"][data-key="'+b.dataset.visualField+'"]'):document.getElementById('t-'+b.dataset.visualField)||document.getElementById(b.dataset.visualField);if(!el||el.disabled)return;el.closest('details')?.setAttribute('open','');el.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});el.focus({preventScroll:true});}document.addEventListener('click',focus);window.HVACVisual={render,geometry,section,button,n,L,svg,label};})();
